29	import org.apache.kafka.coordinator.group.GroupCoordinatorConfig;
30	import org.apache.kafka.coordinator.group.modern.share.ShareGroupConfig;
31	import org.apache.kafka.coordinator.share.ShareCoordinatorConfig;
32	import org.apache.kafka.coordinator.transaction.AddPartitionsToTxnConfig;
33	import org.apache.kafka.coordinator.transaction.TransactionLogConfig;
34	import org.apache.kafka.coordinator.transaction.TransactionStateManagerConfig;
35	import org.apache.kafka.network.SocketServerConfigs;
36	import org.apache.kafka.raft.KRaftConfigs;
37	import org.apache.kafka.raft.MetadataLogConfig;
38	import org.apache.kafka.raft.QuorumConfig;
39	import org.apache.kafka.server.log.remote.storage.RemoteLogManagerConfig;
40	import org.apache.kafka.server.metrics.MetricConfigs;
41	import org.apache.kafka.server.util.Csv;
42	import org.apache.kafka.storage.internals.log.CleanerConfig;
43	import org.apache.kafka.storage.internals.log.LogConfig;
44	
45	import org.apache.commons.validator.routines.InetAddressValidator;
46	
47	import java.util.HashMap;
48	import java.util.List;
49	import java.util.Locale;
50	import java.util.Map;
51	import java.util.Optional;
52	import java.util.Set;
53	import java.util.stream.Collectors;
54	
55	/**
56	 * During moving {@link kafka.server.KafkaConfig} out of core AbstractKafkaConfig will be the future KafkaConfig
57	 * so any new getters, or updates to `CONFIG_DEF` will be defined here.
58	 * Any code depends on kafka.server.KafkaConfig will keep for using kafka.server.KafkaConfig for the time being until we move it out of core
59	 * For more details check KAFKA-15853
60	 */
61	public abstract class AbstractKafkaConfig extends AbstractConfig {
62	
63	    private static final InetAddressValidator INET_ADDRESS_VALIDATOR = InetAddressValidator.getInstance();
64	
65	    public static final ConfigDef CONFIG_DEF = Utils.mergeConfigs(List.of(
66	        RemoteLogManagerConfig.configDef(),
67	        ServerConfigs.CONFIG_DEF,
68	        KRaftConfigs.CONFIG_DEF,
69	        MetadataLogConfig.CONFIG_DEF,
70	        SocketServerConfigs.CONFIG_DEF,
71	        ReplicationConfigs.CONFIG_DEF,
72	        GroupCoordinatorConfig.CONFIG_DEF,
73	        CleanerConfig.CONFIG_DEF,
74	        LogConfig.SERVER_CONFIG_DEF,
75	        ShareGroupConfig.CONFIG_DEF,
76	        ShareCoordinatorConfig.CONFIG_DEF,
77	        TransactionLogConfig.CONFIG_DEF,
78	        TransactionStateManagerConfig.CONFIG_DEF,
79	        QuorumConfig.CONFIG_DEF,
80	        MetricConfigs.CONFIG_DEF,
81	        QuotaConfig.CONFIG_DEF,
82	        BrokerSecurityConfigs.CONFIG_DEF,
83	        DelegationTokenManagerConfigs.CONFIG_DEF,
84	        AddPartitionsToTxnConfig.CONFIG_DEF
85	    ));
86	
87	    public AbstractKafkaConfig(ConfigDef definition, Map<?, ?> originals, Map<String, ?> configProviderProps, boolean doLog) {
88	        super(definition, originals, configProviderProps, doLog);
89	    }
90	
91	    public List<String> logDirs() {
92	        return Optional.ofNullable(getList(ServerLogConfigs.LOG_DIRS_CONFIG)).orElse(getList(ServerLogConfigs.LOG_DIR_CONFIG));
93	    }
94	
95	    public int numIoThreads() {
96	        return getInt(ServerConfigs.NUM_IO_THREADS_CONFIG);
97	    }
98	
99	    public int numReplicaFetchers() {
100	        return getInt(ReplicationConfigs.NUM_REPLICA_FETCHERS_CONFIG);
101	    }
102	
103	    public int numRecoveryThreadsPerDataDir() {
104	        return getInt(ServerLogConfigs.NUM_RECOVERY_THREADS_PER_DATA_DIR_CONFIG);
105	    }
106	
107	    public int backgroundThreads() {
108	        return getInt(ServerConfigs.BACKGROUND_THREADS_CONFIG);
109	    }
110	
111	    public int brokerId() {
112	        return getInt(ServerConfigs.BROKER_ID_CONFIG);
113	    }
114	
115	    public int requestTimeoutMs() {
116	        return getInt(ServerConfigs.REQUEST_TIMEOUT_MS_CONFIG);
117	    }
118	
119	    public List<String> controllerListenerNames() {
120	        return getList(KRaftConfigs.CONTROLLER_LISTENER_NAMES_CONFIG);
121	    }
122	
123	    public ListenerName interBrokerListenerName() {
124	        return interBrokerListenerNameAndSecurityProtocol().getKey();
125	    }
126	
127	    public SecurityProtocol interBrokerSecurityProtocol() {
128	        return interBrokerListenerNameAndSecurityProtocol().getValue();
129	    }
130	
131	    public int initialRegistrationTimeoutMs() {
132	        return getInt(KRaftConfigs.INITIAL_BROKER_REGISTRATION_TIMEOUT_MS_CONFIG);
133	    }
134	
135	    public int brokerHeartbeatIntervalMs() {
136	        return getInt(KRaftConfigs.BROKER_HEARTBEAT_INTERVAL_MS_CONFIG);
137	    }
138	
139	    public Optional<String> rack() {
140	        return Optional.ofNullable(getString(ServerConfigs.BROKER_RACK_CONFIG));
141	    }
142	
143	    public int nodeId() {
144	        return getInt(KRaftConfigs.NODE_ID_CONFIG);
145	    }
146	
147	    public Map<ListenerName, SecurityProtocol> effectiveListenerSecurityProtocolMap() {
148	        Map<ListenerName, SecurityProtocol> mapValue =
149	                getMap(SocketServerConfigs.LISTENER_SECURITY_PROTOCOL_MAP_CONFIG,
150	                        getString(SocketServerConfigs.LISTENER_SECURITY_PROTOCOL_MAP_CONFIG))
151	                        .entrySet()
152	                        .stream()
153	                        .collect(Collectors.toMap(
154	                                e -> ListenerName.normalised(e.getKey()),
155	                                e -> securityProtocol(
156	                                        e.getValue(),
157	                                        SocketServerConfigs.LISTENER_SECURITY_PROTOCOL_MAP_CONFIG)));
158	
159	        if (!originals().containsKey(SocketServerConfigs.LISTENER_SECURITY_PROTOCOL_MAP_CONFIG)) {
160	            // Using the default configuration since listener.security.protocol.map is not explicitly set.
161	            // Before adding default PLAINTEXT mappings for controller listeners, verify that:
162	            // 1. No SSL or SASL protocols are used in controller listeners
163	            // 2. No SSL or SASL protocols are used in regular listeners (Note: controller listeners
164	            //    are not included in 'listeners' config when process.roles=broker)
165	            if (controllerListenerNames().stream().anyMatch(AbstractKafkaConfig::isSslOrSasl) ||
166	                    getList(SocketServerConfigs.LISTENERS_CONFIG).stream()
167	                            .anyMatch(listenerName -> isSslOrSasl(parseListenerName(listenerName)))) {
168	                return mapValue;
169	            } else {
170	                // Add the PLAINTEXT mappings for all controller listener names that are not explicitly PLAINTEXT
171	                mapValue.putAll(controllerListenerNames().stream()
172	                        .filter(listenerName -> !SecurityProtocol.PLAINTEXT.name.equals(listenerName))
173	                        .collect(Collectors.toMap(ListenerName::new, ignored -> SecurityProtocol.PLAINTEXT)));
174	                return mapValue;
175	            }
176	        } else {
177	            return mapValue;
178	        }
179	    }
180	
181	    public static Map<String, String> getMap(String propName, String propValue) {
182	        try {
183	            return Csv.parseCsvMap(propValue);
184	        } catch (Exception e) {
185	            throw new IllegalArgumentException(
186	                    String.format("Error parsing configuration property '%s': %s", propName, e.getMessage()));
187	        }
188	    }
189	
190	    /**
191	     * Copy a configuration map, populating some keys that we want to treat as synonyms.
192	     */
193	    public static Map<Object, Object> populateSynonyms(Map<?, ?> input) {
194	        Map<Object, Object> output = new HashMap<>(input);
195	        Object brokerId = output.get(ServerConfigs.BROKER_ID_CONFIG);
196	        Object nodeId = output.get(KRaftConfigs.NODE_ID_CONFIG);
197	        if (brokerId == null && nodeId != null) {
198	            output.put(ServerConfigs.BROKER_ID_CONFIG, nodeId);
199	        } else if (brokerId != null && nodeId == null) {
200	            output.put(KRaftConfigs.NODE_ID_CONFIG, brokerId);
201	        }
202	        return output;
203	    }
204	
205	    public static List<Endpoint> listenerListToEndPoints(List<String> listeners, Map<ListenerName, SecurityProtocol> securityProtocolMap) {
206	        return listenerListToEndPoints(listeners, securityProtocolMap, true);
207	    }
208	
209	    public static List<Endpoint> listenerListToEndPoints(List<String> listeners, Map<ListenerName, SecurityProtocol> securityProtocolMap, boolean requireDistinctPorts) {
210	        try {
211	            List<Endpoint> endPoints = SocketServerConfigs.listenerListToEndPoints(listeners, securityProtocolMap);
212	            validate(endPoints, listeners, requireDistinctPorts);
213	            return endPoints;
214	        } catch (Exception e) {
215	            throw new IllegalArgumentException(String.format("Error creating broker listeners from '%s': %s", listeners, e.getMessage()), e);
216	        }
217	    }
218	
219	    private static void validate(List<Endpoint> endPoints, List<String> listeners, boolean requireDistinctPorts) {
220	        long distinctListenerNames = endPoints.stream().map(Endpoint::listener).distinct().count();
221	        if (distinctListenerNames != endPoints.size()) {
222	            throw new IllegalArgumentException("Each listener must have a different name, listeners: " + listeners);
223	        }
224	
225	        if (!requireDistinctPorts) return;
226	
227	        endPoints.stream()
228	            .filter(ep -> ep.port() != 0) // filter port 0 for unit tests
229	            .collect(Collectors.groupingBy(Endpoint::port))
230	            .entrySet().stream()
231	            .filter(entry -> entry.getValue().size() > 1)
232	            .forEach(entry -> {
233	                // Iterate through every grouping of duplicates by port to see if they are valid
234	                int port = entry.getKey();
235	                List<Endpoint> eps = entry.getValue();
236	                // Exception case, let's allow duplicate ports if one host is on IPv4 and the other one is on IPv6
237	                Map<Boolean, List<Endpoint>> partitionedByValidIp = eps.stream()
238	                        .collect(Collectors.partitioningBy(ep -> ep.host() != null && INET_ADDRESS_VALIDATOR.isValid(ep.host())));
239	
240	                List<Endpoint> duplicatesWithIpHosts = partitionedByValidIp.get(true);
241	                List<Endpoint> duplicatesWithoutIpHosts = partitionedByValidIp.get(false);
242	
243	                checkDuplicateListenerPorts(duplicatesWithoutIpHosts, listeners);
244	
245	                if (duplicatesWithIpHosts.isEmpty()) return;
246	                if (duplicatesWithIpHosts.size() == 2) {
247	                    String errorMessage = "If you have two listeners on the same port then one needs to be IPv4 and the other IPv6, listeners: " + listeners + ", port: " + port;
248	                    Endpoint ep1 = duplicatesWithIpHosts.get(0);
249	                    Endpoint ep2 = duplicatesWithIpHosts.get(1);
250	                    if (!validateOneIsIpv4AndOtherIpv6(ep1.host(), ep2.host())) {
251	                        throw new IllegalArgumentException(errorMessage);
252	                    }
253	
254	                    // If we reach this point it means that even though duplicatesWithIpHosts in isolation can be valid, if
255	                    // there happens to be ANOTHER listener on this port without an IP host (such as a null host) then its
256	                    // not valid.
257	                    if (!duplicatesWithoutIpHosts.isEmpty()) {
258	                        throw new IllegalArgumentException(errorMessage);
259	                    }
260	                    return;
261	                }
262	                // Having more than 2 duplicate endpoints doesn't make sense since we only have 2 IP stacks (one is IPv4
263	                // and the other is IPv6)
264	                throw new IllegalArgumentException("Each listener must have a different port unless exactly one listener has an IPv4 address and the other IPv6 address, listeners: " + listeners + ", port: " + port);
265	            });
266	    }
267	
268	    private static boolean validateOneIsIpv4AndOtherIpv6(String first, String second) {
269	        return (INET_ADDRESS_VALIDATOR.isValidInet4Address(first) && INET_ADDRESS_VALIDATOR.isValidInet6Address(second)) ||
270	                (INET_ADDRESS_VALIDATOR.isValidInet6Address(first) && INET_ADDRESS_VALIDATOR.isValidInet4Address(second));
271	    }
272	
273	    private static void checkDuplicateListenerPorts(List<Endpoint> endpoints, List<String> listeners) {
274	        Set<Integer> distinctPorts = endpoints.stream().map(Endpoint::port).collect(Collectors.toSet());
275	        if (endpoints.size() != distinctPorts.size()) {
276	            throw new IllegalArgumentException("Each listener must have a different port, listeners: " + listeners);
277	        }
278	    }
279	
280	    private static SecurityProtocol securityProtocol(String protocolName, String configName) {
281	        try {
282	            return SecurityProtocol.forName(protocolName);
283	        } catch (IllegalArgumentException e) {
284	            throw new ConfigException(
285	                    String.format("Invalid security protocol `%s` defined in %s", protocolName, configName));
286	        }
287	    }
288	
289	    private Map.Entry<ListenerName, SecurityProtocol> interBrokerListenerNameAndSecurityProtocol() {
290	        String interBrokerListenerName = getString(ReplicationConfigs.INTER_BROKER_LISTENER_NAME_CONFIG);
291	        if (interBrokerListenerName != null) {
292	            if (originals().containsKey(ReplicationConfigs.INTER_BROKER_SECURITY_PROTOCOL_CONFIG)) {
293	                throw new ConfigException(String.format("Only one of %s and %s should be set.",
294	                        ReplicationConfigs.INTER_BROKER_LISTENER_NAME_CONFIG,
295	                        ReplicationConfigs.INTER_BROKER_SECURITY_PROTOCOL_CONFIG));
296	            }
297	            ListenerName listenerName = ListenerName.normalised(interBrokerListenerName);
298	            SecurityProtocol securityProtocol = effectiveListenerSecurityProtocolMap().get(listenerName);
299	            if (securityProtocol == null) {
300	                throw new ConfigException("Listener with name " + listenerName.value() + " defined in " +
301	                        ReplicationConfigs.INTER_BROKER_LISTENER_NAME_CONFIG + " not found in " +
302	                        SocketServerConfigs.LISTENER_SECURITY_PROTOCOL_MAP_CONFIG + ".");
303	            }
304	            return Map.entry(listenerName, securityProtocol);
305	        } else {
306	            SecurityProtocol securityProtocol = securityProtocol(
307	                    getString(ReplicationConfigs.INTER_BROKER_SECURITY_PROTOCOL_CONFIG),
308	                    ReplicationConfigs.INTER_BROKER_SECURITY_PROTOCOL_CONFIG);
309	            return Map.entry(ListenerName.forSecurityProtocol(securityProtocol), securityProtocol);
310	        }
311	    }
312	
313	    private static boolean isSslOrSasl(String name) {
314	        return name.equals(SecurityProtocol.SSL.name) || name.equals(SecurityProtocol.SASL_SSL.name) ||
315	                name.equals(SecurityProtocol.SASL_PLAINTEXT.name);
316	    }
317	
318	    private static String parseListenerName(String connectionString) {
319	        int firstColon = connectionString.indexOf(':');
320	        if (firstColon < 0) {
321	            throw new KafkaException("Unable to parse a listener name from " + connectionString);
322	        }
323	        return connectionString.substring(0, firstColon).toUpperCase(Locale.ROOT);
324	    }
325	
326	    /**
327	     * Registers a component for dynamic reconfiguration notifications.
328	     * <p>
329	     * This method exists to support migration from kafka.server.KafkaConfig (Scala/core) to AbstractKafkaConfig (Java/server).
330	     * When migrating code, replace KafkaConfig references with AbstractKafkaConfig.
331	     *
332	     * @param reconfigurable the component to register for configuration updates
333	     */
334	    public abstract void addReconfigurable(Reconfigurable reconfigurable);
335	
336	    /**
337	     * Unregisters a component from dynamic reconfiguration notifications.
338	     * <p>
339	     * This method exists to support migration from kafka.server.KafkaConfig (Scala/core) to AbstractKafkaConfig (Java/server).
340	     * When migrating code, replace KafkaConfig references with AbstractKafkaConfig.
341	     *
342	     * @param reconfigurable the component to unregister
343	     */
344	    public abstract void removeReconfigurable(Reconfigurable reconfigurable);
345	}
