193	    public static Map<Object, Object> populateSynonyms(Map<?, ?> input) {
194	        Map<Object, Object> output = new HashMap<>(input);
195	        Object brokerId = output.get(ServerConfigs.BROKER_ID_CONFIG);
196	        Object nodeId = output.get(KRaftConfigs.NODE_ID_CONFIG);
197	        if (brokerId == null && nodeId != null) {
198	            output.put(ServerConfigs.BROKER_ID_CONFIG, nodeId);
199	        } else if (brokerId != null && nodeId == null) {
200	            output.put(KRaftConfigs.NODE_ID_CONFIG, brokerId);
201	        }
202	        return output;
203	    }
