209	    public static List<Endpoint> listenerListToEndPoints(List<String> listeners, Map<ListenerName, SecurityProtocol> securityProtocolMap, boolean requireDistinctPorts) {
210	        try {
211	            List<Endpoint> endPoints = SocketServerConfigs.listenerListToEndPoints(listeners, securityProtocolMap);
212	            validate(endPoints, listeners, requireDistinctPorts);
213	            return endPoints;
214	        } catch (Exception e) {
215	            throw new IllegalArgumentException(String.format("Error creating broker listeners from '%s': %s", listeners, e.getMessage()), e);
216	        }
217	    }
218	
219	    private static void validate(List<Endpoint> endPoints, List<String> listeners, boolean requireDistinctPorts) {
220	        long distinctListenerNames = endPoints.stream().map(Endpoint::listener).distinct().count();
221	        if (distinctListenerNames != endPoints.size()) {
222	            throw new IllegalArgumentException("Each listener must have a different name, listeners: " + listeners);
223	        }
224	
225	        if (!requireDistinctPorts) return;
226	
227	        endPoints.stream()
228	            .filter(ep -> ep.port() != 0) // filter port 0 for unit tests
229	            .collect(Collectors.groupingBy(Endpoint::port))
230	            .entrySet().stream()
231	            .filter(entry -> entry.getValue().size() > 1)
232	            .forEach(entry -> {
233	                // Iterate through every grouping of duplicates by port to see if they are valid
234	                int port = entry.getKey();
235	                List<Endpoint> eps = entry.getValue();
236	                // Exception case, let's allow duplicate ports if one host is on IPv4 and the other one is on IPv6
237	                Map<Boolean, List<Endpoint>> partitionedByValidIp = eps.stream()
238	                        .collect(Collectors.partitioningBy(ep -> ep.host() != null && INET_ADDRESS_VALIDATOR.isValid(ep.host())));
239	
240	                List<Endpoint> duplicatesWithIpHosts = partitionedByValidIp.get(true);
241	                List<Endpoint> duplicatesWithoutIpHosts = partitionedByValidIp.get(false);
242	
243	                checkDuplicateListenerPorts(duplicatesWithoutIpHosts, listeners);
244	
245	                if (duplicatesWithIpHosts.isEmpty()) return;
246	                if (duplicatesWithIpHosts.size() == 2) {
247	                    String errorMessage = "If you have two listeners on the same port then one needs to be IPv4 and the other IPv6, listeners: " + listeners + ", port: " + port;
248	                    Endpoint ep1 = duplicatesWithIpHosts.get(0);
249	                    Endpoint ep2 = duplicatesWithIpHosts.get(1);
250	                    if (!validateOneIsIpv4AndOtherIpv6(ep1.host(), ep2.host())) {
251	                        throw new IllegalArgumentException(errorMessage);
252	                    }
253	
254	                    // If we reach this point it means that even though duplicatesWithIpHosts in isolation can be valid, if
255	                    // there happens to be ANOTHER listener on this port without an IP host (such as a null host) then its
256	                    // not valid.
257	                    if (!duplicatesWithoutIpHosts.isEmpty()) {
258	                        throw new IllegalArgumentException(errorMessage);
259	                    }
260	                    return;
261	                }
262	                // Having more than 2 duplicate endpoints doesn't make sense since we only have 2 IP stacks (one is IPv4
263	                // and the other is IPv6)
264	                throw new IllegalArgumentException("Each listener must have a different port unless exactly one listener has an IPv4 address and the other IPv6 address, listeners: " + listeners + ", port: " + port);
265	            });
266	    }
267	
268	    private static boolean validateOneIsIpv4AndOtherIpv6(String first, String second) {
269	        return (INET_ADDRESS_VALIDATOR.isValidInet4Address(first) && INET_ADDRESS_VALIDATOR.isValidInet6Address(second)) ||
270	                (INET_ADDRESS_VALIDATOR.isValidInet6Address(first) && INET_ADDRESS_VALIDATOR.isValidInet4Address(second));
271	    }
272	
273	    private static void checkDuplicateListenerPorts(List<Endpoint> endpoints, List<String> listeners) {
274	        Set<Integer> distinctPorts = endpoints.stream().map(Endpoint::port).collect(Collectors.toSet());
275	        if (endpoints.size() != distinctPorts.size()) {
276	            throw new IllegalArgumentException("Each listener must have a different port, listeners: " + listeners);
277	        }
278	    }
279	
280	    private static SecurityProtocol securityProtocol(String protocolName, String configName) {
281	        try {
282	            return SecurityProtocol.forName(protocolName);
283	        } catch (IllegalArgumentException e) {
284	            throw new ConfigException(
285	                    String.format("Invalid security protocol `%s` defined in %s", protocolName, configName));
286	        }
287	    }
288	
289	    private Map.Entry<ListenerName, SecurityProtocol> interBrokerListenerNameAndSecurityProtocol() {
290	        String interBrokerListenerName = getString(ReplicationConfigs.INTER_BROKER_LISTENER_NAME_CONFIG);
291	        if (interBrokerListenerName != null) {
292	            if (originals().containsKey(ReplicationConfigs.INTER_BROKER_SECURITY_PROTOCOL_CONFIG)) {
293	                throw new ConfigException(String.format("Only one of %s and %s should be set.",
294	                        ReplicationConfigs.INTER_BROKER_LISTENER_NAME_CONFIG,
295	                        ReplicationConfigs.INTER_BROKER_SECURITY_PROTOCOL_CONFIG));
296	            }
297	            ListenerName listenerName = ListenerName.normalised(interBrokerListenerName);
298	            SecurityProtocol securityProtocol = effectiveListenerSecurityProtocolMap().get(listenerName);
299	            if (securityProtocol == null) {
300	                throw new ConfigException("Listener with name " + listenerName.value() + " defined in " +
301	                        ReplicationConfigs.INTER_BROKER_LISTENER_NAME_CONFIG + " not found in " +
302	                        SocketServerConfigs.LISTENER_SECURITY_PROTOCOL_MAP_CONFIG + ".");
303	            }
304	            return Map.entry(listenerName, securityProtocol);
305	        } else {
306	            SecurityProtocol securityProtocol = securityProtocol(
307	                    getString(ReplicationConfigs.INTER_BROKER_SECURITY_PROTOCOL_CONFIG),
308	                    ReplicationConfigs.INTER_BROKER_SECURITY_PROTOCOL_CONFIG);
309	            return Map.entry(ListenerName.forSecurityProtocol(securityProtocol), securityProtocol);
310	        }
311	    }
312	
313	    private static boolean isSslOrSasl(String name) {
314	        return name.equals(SecurityProtocol.SSL.name) || name.equals(SecurityProtocol.SASL_SSL.name) ||
315	                name.equals(SecurityProtocol.SASL_PLAINTEXT.name);
316	    }
317	
318	    private static String parseListenerName(String connectionString) {
319	        int firstColon = connectionString.indexOf(':');
320	        if (firstColon < 0) {
321	            throw new KafkaException("Unable to parse a listener name from " + connectionString);
322	        }
323	        return connectionString.substring(0, firstColon).toUpperCase(Locale.ROOT);
324	    }
